import React from "react";
import Home from "./components/Home/Home";
import Header from "./components/Header";
import "./App.css";

function App() {
  return (
    <div className="main-wrapper">
      <Header />
      <Home />
      <div className="f-footer">
        <div className="a-container--full f-footer__container">
          <div className="a-flex a-flex--align-center a-gap--s:m a-gap--xs:s a-gap--xxs:xs a-gap--xxxs">
            <div className="a-flex__item f-footer__logo">
              <p className="f-logo">
                <a aria-label="Go to Homepage" href="" rel="home">
                  <img
                    alt="Devites.Agency — Web Design & Development Agency"
                    className="f-logo__img"
                    decoding="async"
                    fetchpriority="high"
                    height="32"
                    src={deviteslogo}
                    width="168"
                  />
                </a>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
